CREATE TABLE characters ( character_name TEXT PRIMARY KEY, account_name TEXT NOT NULL, created_at TEXT NOT NULL, underwear_type INTEGER NOT NULL DEFAULT 0, hair_color INTEGER NOT NULL DEFAULT 0, hair_style INTEGER NOT NULL DEFAULT 0, skin_color INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL, exp INTEGER NOT NULL, map_name TEXT NOT NULL, map_x INTEGER NOT NULL, map_y INTEGER NOT NULL, hp INTEGER NOT NULL, mp INTEGER NOT NULL, sp INTEGER NOT NULL, str INTEGER NOT NULL, vit INTEGER NOT NULL, dex INTEGER NOT NULL, intl INTEGER NOT NULL, mag INTEGER NOT NULL, chr INTEGER NOT NULL, gender INTEGER NOT NULL, skin INTEGER NOT NULL, hairstyle INTEGER NOT NULL, haircolor INTEGER NOT NULL, underwear INTEGER NOT NULL, profile TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', rating INTEGER NOT NULL DEFAULT 0, luck INTEGER NOT NULL DEFAULT 0, lu_pool INTEGER NOT NULL DEFAULT 0, enemy_kill_count INTEGER NOT NULL DEFAULT 0, pk_count INTEGER NOT NULL DEFAULT 0, reward_gold INTEGER NOT NULL DEFAULT 0, downskill_index INTEGER NOT NULL DEFAULT -1, id_num1 INTEGER NOT NULL DEFAULT 0, id_num2 INTEGER NOT NULL DEFAULT 0, id_num3 INTEGER NOT NULL DEFAULT 0, hunger_status INTEGER NOT NULL DEFAULT 100, timeleft_rating INTEGER NOT NULL DEFAULT 0, timeleft_force_recall INTEGER NOT NULL DEFAULT 0, timeleft_firm_staminar INTEGER NOT NULL DEFAULT 0, penalty_block_year INTEGER NOT NULL DEFAULT 0, penalty_block_month INTEGER NOT NULL DEFAULT 0, penalty_block_day INTEGER NOT NULL DEFAULT 0, quest_number INTEGER NOT NULL DEFAULT 0, quest_id INTEGER NOT NULL DEFAULT 0, current_quest_count INTEGER NOT NULL DEFAULT 0, quest_reward_type INTEGER NOT NULL DEFAULT 0, quest_reward_amount INTEGER NOT NULL DEFAULT 0, contribution INTEGER NOT NULL DEFAULT 0, war_contribution INTEGER NOT NULL DEFAULT 0, quest_completed INTEGER NOT NULL DEFAULT 0, special_event_id INTEGER NOT NULL DEFAULT 0, super_attack_left INTEGER NOT NULL DEFAULT 0, special_ability_time INTEGER NOT NULL DEFAULT 0, locked_map_name TEXT NOT NULL DEFAULT '', locked_map_time INTEGER NOT NULL DEFAULT 0, crusade_job INTEGER NOT NULL DEFAULT 0, crusade_guid INTEGER NOT NULL DEFAULT 0, construct_point INTEGER NOT NULL DEFAULT 0, dead_penalty_time INTEGER NOT NULL DEFAULT 0, party_id INTEGER NOT NULL DEFAULT 0, gizon_item_upgrade_left INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(account_name) REFERENCES accounts(account_name) ON DELETE CASCADE);

CREATE INDEX idx_characters_account ON characters(account_name);
